class Solution {
public:
    bool isGood(vector<int>& nums) {
        int n = nums.size();
        if (n < 2) return false;
        int base_n = n - 1;
        unordered_map<int, int> counts;
        for (int x : nums) counts[x]++;
        for (int i = 1; i < base_n; ++i) {
            if (counts[i] != 1) return false;
        }
        return counts[base_n] == 2 && counts.size() == base_n;
    }
};

import java.util.HashMap;
import java.util.Map;

class Solution {
    public boolean isGood(int[] nums) {
        int n = nums.length;
        if (n < 2) return false;
        int baseN = n - 1;
        Map<Integer, Integer> counts = new HashMap<>();
        for (int x : nums) {
            counts.put(x, counts.getOrDefault(x, 0) + 1);
        }
        for (int i = 1; i < baseN; i++) {
            if (counts.getOrDefault(i, 0) != 1) return false;
        }
        return counts.getOrDefault(baseN, 0) == 2 && counts.size() == baseN;
    }
}

/**
 * @param {number[]} nums
 * @return {boolean}
