var isGood = function(nums) {
    const n = nums.length;
    if (n < 2) return false;
    const baseN = n - 1;
    const counts = new Map();
    for (const x of nums) {
        counts.set(x, (counts.get(x) || 0) + 1);
    }
    for (let i = 1; i < baseN; i++) {
        if (counts.get(i) !== 1) return false;
    }
    return counts.get(baseN) === 2 && counts.size === baseN;
};
